command:
$ErrorActionPreference = 'Stop'
$workspace = 'D:\GitHub\Forge-Conductor-Windows-Edition'
. (Join-Path $workspace '.forge-codex\instructions\scripts\Common.ps1')
$evidenceRelative = '.forge-codex\state\evidence\P16\manager-terminal-pipe-transition-watchdog-checkpoint.json'
$evidencePath = Join-Path $workspace $evidenceRelative
$evidence = Get-Content -Raw -LiteralPath $evidencePath | ConvertFrom-Json
$sourceProperties = @($evidence.source_sha256.PSObject.Properties)
if ($sourceProperties.Count -ne 13) { throw "Unexpected source hash count: $($sourceProperties.Count)" }
foreach ($property in $sourceProperties) {
    $actual = Get-FileSha256 -Path (Join-Path $workspace $property.Name)
    if ($actual -ne [string]$property.Value) { throw "Source hash mismatch: $($property.Name)" }
}
$binaryPaths = [ordered]@{
    'ForgeConductor.Manager.TransitionWorkerTests.exe' = 'out\build\windows-msvc-x64\bin\Debug\ForgeConductor.Manager.TransitionWorkerTests.exe'
    'ForgeConductor.Manager.ProcessRestartSignalTests.exe' = 'out\build\windows-msvc-x64\bin\Debug\ForgeConductor.Manager.ProcessRestartSignalTests.exe'
    'ForgeConductor.Manager.ProcessHostTests.exe' = 'out\build\windows-msvc-x64\bin\Debug\ForgeConductor.Manager.ProcessHostTests.exe'
    'ForgeConductor.Manager.WindowsInfrastructureTests.exe' = 'out\build\windows-msvc-x64\bin\Debug\ForgeConductor.Manager.WindowsInfrastructureTests.exe'
    'ForgeConductor.Infrastructure.HeaderSelfContainment.exe' = 'out\build\windows-msvc-x64\bin\Debug\ForgeConductor.Infrastructure.HeaderSelfContainment.exe'
    'ForgeConductor.Manager.Host.lib' = 'out\build\windows-msvc-x64\lib\Debug\ForgeConductor.Manager.Host.lib'
    'ForgeConductor.Infrastructure.Windows.lib' = 'out\build\windows-msvc-x64\lib\Debug\ForgeConductor.Infrastructure.Windows.lib'
}
if (@($evidence.binary_sha256.PSObject.Properties).Count -ne $binaryPaths.Count) { throw 'Unexpected binary hash count.' }
foreach ($entry in $binaryPaths.GetEnumerator()) {
    $actual = Get-FileSha256 -Path (Join-Path $workspace $entry.Value)
    if ($actual -ne [string]$evidence.binary_sha256.($entry.Key)) { throw "Binary hash mismatch: $($entry.Key)" }
}
$commandRecords = @(
    @('.forge-codex\state\commands\20260830T102222416Z-d2c2c1c9.json', [string]$evidence.recorded_build.command_record_sha256),
    @('.forge-codex\state\commands\20260830T102303043Z-a21e942f.json', [string]$evidence.recorded_validation.command_record_sha256)
)
foreach ($record in $commandRecords) {
    $actual = Get-FileSha256 -Path (Join-Path $workspace $record[0])
    if ($actual -ne $record[1]) { throw "Command-record hash mismatch: $($record[0])" }
}
& (Join-Path $workspace '.forge-codex\instructions\scripts\Validate-NoPython.ps1') -WorkspaceRoot $workspace
& (Join-Path $workspace '.forge-codex\instructions\scripts\Validate-NoAttribution.ps1') -WorkspaceRoot $workspace
& (Join-Path $workspace '.forge-codex\instructions\scripts\Verify-Ledger.ps1') -WorkspaceRoot $workspace
$diffOutput = & git -C $workspace diff --check 2>&1
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed: $diffOutput" }
$changedTextFiles = @($sourceProperties.Name) + $evidenceRelative
$strictUtf8 = [Text.UTF8Encoding]::new($false, $true)
foreach ($relative in $changedTextFiles) {
    $bytes = [IO.File]::ReadAllBytes((Join-Path $workspace $relative))
    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xef -and $bytes[1] -eq 0xbb -and $bytes[2] -eq 0xbf) { throw "UTF-8 BOM is forbidden: $relative" }
    $text = $strictUtf8.GetString($bytes)
    if ($text -match '(?<!\r)\n' -or $text -match '\r(?!\n)') { throw "Non-CRLF line ending: $relative" }
    foreach ($line in [regex]::Split($text, '\r\n')) {
        if ($line -match '[ \t]+$') { throw "Trailing whitespace: $relative" }
    }
}
Write-Output "Source hashes matched: $($sourceProperties.Count)"
Write-Output "Binary hashes matched: $($binaryPaths.Count)"
Write-Output "Command records matched: $($commandRecords.Count)"
Write-Output "Changed text files CRLF UTF-8 no BOM: $($changedTextFiles.Count)"
Write-Output 'git diff --check passed.'
exit 0
